using System.Reflection;using System.Runtime.Loader;using System.Text.Json;using System.Collections;
AssemblyLoadContext.Default.Resolving+=(c,n)=>{foreach(var root in args.Skip(1)){var p=Path.Combine(root,n.Name+".dll");if(File.Exists(p))return c.LoadFromAssemblyPath(p);}return null;};
var asm=AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.GetFullPath(args[0]));
var phone=asm.GetType("OmniToolbox.LocalModules.PhoneChat",true)!;
var type=phone.GetNestedType("FishSchedule")!;var engine=Activator.CreateInstance(type)!;
long now=2000000000000;int checks=0;
void Check(bool x,string name){if(!x)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
JsonElement Rows(params object[] rows)=>JsonSerializer.SerializeToElement(rows);
object Row(string key,long at,long expires)=>new{key,title="测试鱼",body="测试钓场",at,expires};
void Replace(string owner,JsonElement rows,bool enabled=true,int mode=0,long? time=null)=>type.GetMethod("Replace")!.Invoke(engine,[owner,rows,enabled,mode,time??now]);
IList Due(long at)=>(IList)type.GetMethod("TakeDue")!.Invoke(engine,[at])!;
string State()=>JsonSerializer.Serialize(engine,type);
void Reject(Action action,string name){try{action();throw new Exception("accepted invalid");}catch(TargetInvocationException e){Check(e.InnerException!=null,name);}}
Replace("a",Rows(Row("start",now+2000,now+20000),Row("before",now+1000,now+20000),Row("before",now+1000,now+20000)));
Check(Due(now).Count==0,"future windows do not fire early");
Check(Due(now+1000).Count==1,"duplicate input schedules emit once at the due time");
Check(Due(now+1000).Count==0,"timer retries do not duplicate reminders");
engine=JsonSerializer.Deserialize(State(),type)!;
Check(Due(now+1000).Count==0,"persisted claims survive module restart");
Check(Due(now+2000).Count==1,"remaining future schedule survives restart");
Replace("a",Rows(Row("cancel",now+4000,now+20000)));Replace("a",Rows());
Check(Due(now+4000).Count==0,"unsubscribing replaces and cancels earlier plans");
Replace("a",Rows(Row("pause",now+4000,now+20000)),false);
Check(Due(now+4000).Count==0,"paused plans never emit");
Replace("a",Rows(Row("resume",now+5000,now+20000)),true,2);
var due=Due(now+5000);Check(due.Count==1&&(int)due[0]!.GetType().GetField("Item3")!.GetValue(due[0])! ==2,"explicit QQ/push mode survives scheduling");
Replace("a",Rows(Row("expired",now+1000,now+2000),Row("stale",now+1000,now+3000000)));
Check(Due(now+1000000).Count==0,"expired windows and reminders delayed over15min are dropped");
Replace("a",Rows(Row("one",now+1000,now+20000)));Replace("b",Rows(Row("two",now+1000,now+20000)));
Check(Due(now+1000).Count==2,"separate authorized devices retain independent schedules");
Reject(()=>Replace("a",Rows(Row("far",now+31L*86400000,now+32L*86400000))),"out-of-horizon schedule rejected");
Reject(()=>Replace("a",Rows(Row("bad",now+1000,now))),"invalid expiry rejected");
Reject(()=>Replace("a",Rows(),true,99),"unknown notification route rejected");
Reject(()=>Replace("a",Rows(Enumerable.Range(0,1001).Select(i=>Row("x"+i,now+1000,now+2000)).ToArray())),"oversized queue rejected");
Replace("a",Rows(Row("safe",now+5000,now+20000)));
string previous=State();Reject(()=>Replace("a",Rows(Row("",now+1000,now+2000))),"empty identity rejected");
Check(previous==State(),"invalid replacement preserves last valid schedule");

var normalized=(string[])phone.GetMethod("NormalizePages")!.Invoke(null,[new[]{"fishing","chat","fishing","unknown"}])!;
Check(normalized[0]=="fishing"&&normalized[1]=="chat"&&normalized.Distinct().Count()==12&&!normalized.Contains("unknown"),"server navigation normalization keeps order and drops duplicate/unknown keys");
var navAllowed=phone.GetMethod("NavigationPageEnabled")!;
bool Allowed(string id,bool on,bool ready)=>(bool)navAllowed.Invoke(null,[id,on,ready])!;
Check(!Allowed("itemSearch",true,false)&&!Allowed("collections",true,false),"Omni pages cannot be enabled without loaded Omni");
Check(Allowed("itemSearch",true,true)&&Allowed("collections",true,true),"detected Omni allows requested pages");
Check(!Allowed("itemSearch",false,true)&&!Allowed("collections",false,true),"detecting Omni preserves manually disabled pages");
Check(Allowed("chat",true,false)&&Allowed("wiki",true,false),"Omni absence does not disable unrelated pages");
var flags=BindingFlags.Instance|BindingFlags.NonPublic;
var instance=System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(phone);
void Set(string field,object value)=>phone.GetField(field,flags)!.SetValue(instance,value);
Set("gameState",new Dictionary<string,object>{{"gate",new object()}});Set("enabled",true);
var settingsType=phone.GetNestedType("Settings",BindingFlags.NonPublic)!;var settings=Activator.CreateInstance(settingsType,true)!;Set("settings",settings);
settingsType.GetProperty("DisabledPages")!.SetValue(settings,new List<string>{"fishing","stream"});
Check(!(bool)phone.GetMethod("PageEnabled",flags)!.Invoke(instance,["fishing"])!&&(bool)phone.GetMethod("PageEnabled",flags)!.Invoke(instance,["chat"])!,"server enforces configured page enable flags");
settingsType.GetProperty("PageOrder")!.SetValue(settings,new List<string>{"chat","accounts","fishing"});
var nav=(object[])phone.GetMethod("PageNavigation",flags)!.Invoke(instance,[])!;
var navJson=JsonSerializer.SerializeToElement(nav);Check(navJson[0].GetProperty("id").GetString()=="chat"&&!navJson[2].GetProperty("enabled").GetBoolean(),"poll metadata carries authoritative order and feature switches");
var absent=(object[])phone.GetMethod("PageNavigation",flags)!.Invoke(instance,[])!;var absentJson=JsonSerializer.SerializeToElement(absent);
Check(absentJson.EnumerateArray().Where(p=>new[]{"itemSearch","collections"}.Contains(p.GetProperty("id").GetString())).All(p=>!p.GetProperty("enabled").GetBoolean()&&!p.GetProperty("available").GetBoolean()&&p.GetProperty("reason").GetString()!.Contains("Omni")),"phone metadata hides unavailable Omni pages and explains why");
Set("omniNavigationReady",true);var presentJson=JsonSerializer.SerializeToElement((object[])phone.GetMethod("PageNavigation",flags)!.Invoke(instance,[])!);
Check(presentJson.EnumerateArray().Where(p=>new[]{"itemSearch","collections"}.Contains(p.GetProperty("id").GetString())).All(p=>p.GetProperty("enabled").GetBoolean()&&p.GetProperty("available").GetBoolean()),"Omni detection restores configured availability in phone metadata");
var storeType=phone.GetNestedType("DiskChatStore",BindingFlags.NonPublic)!;
string dir="D:/Yanjiu.Dalamud/tests/fishing-server-075";Directory.CreateDirectory(dir);
var store=Activator.CreateInstance(storeType,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,[Path.Combine(dir,Guid.NewGuid()+".db"),true],null)!;Set("entries",store);
var devicesField=phone.GetField("authorizedDevices",flags)!;var devices=(IList)Activator.CreateInstance(devicesField.FieldType)!;Set("authorizedDevices",devices);
var deviceType=phone.GetNestedType("AuthorizedDevice")!;var device=Activator.CreateInstance(deviceType)!;deviceType.GetProperty("lastPoll")!.SetValue(device,DateTime.UtcNow);devices.Add(device);
Set("listener",new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0));
var routerType=phone.GetNestedType("PushRouter")!;var profileType=phone.GetNestedType("PushProfile")!;var entryType=phone.GetNestedType("ChatEntry")!;
var profile=Activator.CreateInstance(profileType)!;profileType.GetField("provider")!.SetValue(profile,0);profileType.GetField("qqEnabled")!.SetValue(profile,true);profileType.GetField("qq")!.SetValue(profile,"123456");profileType.GetField("direct")!.SetValue(profile,false);
var factory=System.Linq.Expressions.Expression.Lambda(typeof(Func<>).MakeGenericType(profileType),System.Linq.Expressions.Expression.Constant(profile,profileType)).Compile();
var parameter=System.Linq.Expressions.Expression.Parameter(entryType);
var fallback=System.Linq.Expressions.Expression.Lambda(typeof(Action<>).MakeGenericType(entryType),System.Linq.Expressions.Expression.Empty(),parameter).Compile();
object Router()=>Activator.CreateInstance(routerType,[factory,(Action<string>)(_=>{}),fallback,null!,null!,false,null!])!;
var standard=Router();var external=Router();Set("pushRouter",standard);Set("fishPushRouter",external);
int Count(object router)=>(int)routerType.GetField("jobs",flags)!.GetValue(router)!.GetType().GetProperty("Count")!.GetValue(routerType.GetField("jobs",flags)!.GetValue(router))!;
var rowType=phone.GetNestedType("FishRow")!;object Fish(string key){var row=Activator.CreateInstance(rowType)!;rowType.GetProperty("key")!.SetValue(row,key);rowType.GetProperty("title")!.SetValue(row,"测试鱼提醒");rowType.GetProperty("body")!.SetValue(row,"测试内容");return row;}
var deliver=phone.GetMethod("DeliverFish",flags)!;
deliver.Invoke(instance,[Fish("app"),1]);Check(Count(standard)==0&&Count(external)==0,"App-only route never queues QQ or cloud");
var notices=(Array)storeType.GetMethod("NoticesAfter")!.Invoke(store,[0L])!;var first=notices.GetValue(0)!;
Check((string)entryType.GetProperty("channel")!.GetValue(first)! =="鱼糕"&&(string)entryType.GetProperty("target")!.GetValue(first)! =="app","App notice preserves fish title and stable dedupe key");
deliver.Invoke(instance,[Fish("external"),2]);Check(Count(external)==1&&Count(standard)==0,"explicit external route queues even while an App receiver is online");
deliver.Invoke(instance,[Fish("automatic-online"),0]);Check(Count(standard)==0,"automatic route chooses direct App while online");
Set("listener",null!);deliver.Invoke(instance,[Fish("automatic-offline"),0]);Check(Count(standard)==1,"automatic route queues configured push when App is offline");
var core=phone.GetMethod("DeliverFishCore",flags)!;core.Invoke(instance,[Fish("explicit-test"),2,true]);
notices=(Array)storeType.GetMethod("NoticesAfter")!.Invoke(store,[0L])!;
var testNotice=notices.Cast<object>().Single(x=>(string)entryType.GetProperty("target")!.GetValue(x)! =="explicit-test");
Check(!(bool)entryType.GetProperty("externalPush")!.GetValue(testNotice)!&&Count(external)==2,"explicit test keeps App delivery enabled while also using configured external push");
settingsType.GetProperty("DisabledPages")!.SetValue(settings,new List<string>());
Set("fishGate",new object());var schedule=Activator.CreateInstance(type)!;Set("fishSchedule",schedule);
deviceType.GetProperty("id")!.SetValue(device,"fixture");deviceType.GetProperty("token")!.SetValue(device,"test-token");
var plan=type.GetMethod("Get")!.Invoke(schedule,["fixture"])!;plan.GetType().GetProperty("enabled")!.SetValue(plan,false);plan.GetType().GetProperty("mode")!.SetValue(plan,2);
var action=phone.GetMethod("FishingAction",flags)!;var receipt=action.Invoke(instance,[JsonSerializer.SerializeToElement(new{action="test"}),"Bearer test-token"])!;
var receiptJson=JsonSerializer.SerializeToElement(receipt);string receiptKey=receiptJson.GetProperty("testNotice").GetProperty("key").GetString()!;
notices=(Array)storeType.GetMethod("NoticesAfter")!.Invoke(store,[0L])!;
Check(notices.Cast<object>().Any(x=>(string)entryType.GetProperty("target")!.GetValue(x)! ==receiptKey),"test response returns the same stable key as App notice for one-time delivery");
Check(!receiptJson.GetProperty("enabled").GetBoolean()&&receiptJson.GetProperty("testNotice").GetProperty("title").GetString()=="鱼糕测试通知","explicit test works even with scheduled reminders paused and no selected fish");
((IDisposable)standard).Dispose();((IDisposable)external).Dispose();((IDisposable)store).Dispose();
Console.WriteLine(checks+" server schedule/navigation/routing checks passed; no external messages sent.");
